import copy
import math
import unittest
from fractions import Fraction

from solution import summarize_classification


class SummarizeClassificationTests(unittest.TestCase):
    def test_selects_greatest_and_calculates_percentage(self):
        scores = {"cat": 1, "dog": 3, "bird": 0}
        details = {"cat": "C", "dog": {"evidence": [1]}, "bird": None}
        self.assertEqual(summarize_classification(scores, details), {
            "label": "dog", "confidence": 75.0,
            "details": {"evidence": [1]},
        })

    def test_lexicographically_smallest_tie_and_rounding(self):
        result = summarize_classification(
            {"zeta": 2, "alpha": 2, "other": 2},
            {"zeta": 1, "alpha": 2, "other": 3},
        )
        self.assertEqual(result, {"label": "alpha", "confidence": 33.33, "details": 2})

    def test_real_number_types(self):
        result = summarize_classification(
            {"a": Fraction(1, 4), "b": Fraction(3, 4)},
            {"a": "A", "b": "B"},
        )
        self.assertEqual(result, {"label": "b", "confidence": 75.0, "details": "B"})

    def test_details_are_deep_copied_and_inputs_unchanged(self):
        scores = {"winner": 2, "other": 1}
        selected = {"nested": [[1]]}
        details = {"winner": selected, "other": {"x": []}}
        scores_before = copy.deepcopy(scores)
        details_before = copy.deepcopy(details)
        result = summarize_classification(scores, details)
        self.assertEqual(scores, scores_before)
        self.assertEqual(details, details_before)
        self.assertIsNot(result["details"], selected)
        result["details"]["nested"][0].append(2)
        self.assertEqual(selected, {"nested": [[1]]})

    def test_malformed_scores(self):
        malformed = [
            {},
            {"": 1},
            {1: 1},
            {"a": True},
            {"a": "1"},
            {"a": -1},
            {"a": float("nan")},
            {"a": float("inf")},
            {"a": float("-inf")},
            {"a": 0, "b": 0.0},
        ]
        for scores in malformed:
            with self.subTest(scores=scores):
                with self.assertRaises(ValueError):
                    summarize_classification(scores, {"a": None, "b": None, "": None, 1: None})

    def test_scores_and_details_must_be_dictionaries_with_complete_details(self):
        for scores in (None, [], (("a", 1),)):
            with self.subTest(scores=scores):
                with self.assertRaises(ValueError):
                    summarize_classification(scores, {"a": 1})
        for details in (None, [], (("a", 1),)):
            with self.subTest(details=details):
                with self.assertRaises(ValueError):
                    summarize_classification({"a": 1}, details)
        with self.assertRaises(ValueError):
            summarize_classification({"a": 1, "b": 2}, {"b": "only b"})


if __name__ == "__main__":
    unittest.main()

